                    <path x-show="mobileMenuOpen" x-cloak stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
                </svg>
            </button>
        </div>
    </div>

    <!-- Mobile Drawer Menu -->
    <div x-show="mobileMenuOpen" 
         x-cloak
         x-transition:enter="transition ease-out duration-200"
         x-transition:enter-start="opacity-0 -translate-y-4"
         x-transition:enter-end="opacity-100 translate-y-0"
         x-transition:leave="transition ease-in duration-150"
         x-transition:leave-start="opacity-100 translate-y-0"
         x-transition:leave-end="opacity-0 -translate-y-4"
         @click.away="mobileMenuOpen = false"
         class="md:hidden bg-[#FFF8ED] border-b border-[#8888881A] px-4 pt-3 pb-6 space-y-3 shadow-lg">
        <a href="{{ route('home') }}" 
           @click="mobileMenuOpen = false"
           class="block py-2 text-base font-medium {{ request()->routeIs('home') ? 'text-[#693D22] font-semibold' : 'text-[#333333]' }}">
            Home
        </a>
        <a href="{{ route('category.show', 'indoor') }}" 
           @click="mobileMenuOpen = false"
           class="block py-2 text-base font-medium {{ request()->routeIs('category.show') ? 'text-[#693D22] font-semibold' : 'text-[#333333]' }}">
            Product
        </a>
        <a href="{{ route('about') }}" 
           @click="mobileMenuOpen = false"
           class="block py-2 text-base font-medium {{ request()->routeIs('about') ? 'text-[#693D22] font-semibold' : 'text-[#333333]' }}">
            About Us
        </a>
        <a href="{{ route('home') }}#contact" 
           @click="mobileMenuOpen = false"
           class="block py-2 text-base font-medium text-[#333333]">
            Contact
        </a>
    </div>
</header>

